<script setup>
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api, money, dateTime, useRequestError } from '../api'
import PageHeading from '../components/PageHeading.vue'
const onError=useRequestError();const rows=ref([]);const products=ref([]);const loading=ref(false);const dialog=ref(false);const saving=ref(false);const form=ref({product_id:'',quantity:1,unit_cost:'',supplier:'',note:''});const amount=computed(()=>Math.round(Number(form.value.unit_cost||0)*100)*Number(form.value.quantity||0))
async function load(){loading.value=true;try{const [p,r]=await Promise.all([api.products('?page_size=100'),api.purchases()]);products.value=p.items;rows.value=r.items}catch(e){onError(e)}finally{loading.value=false}}
function open(){form.value={product_id:'',quantity:1,unit_cost:'',supplier:'',note:''};dialog.value=true}
async function submit(){if(!form.value.product_id||form.value.quantity<1){ElMessage.warning('请选择商品并填写入库数量');return}saving.value=true;try{await api.receivePurchase({product_id:form.value.product_id,quantity:Number(form.value.quantity),unit_cost_cents:Math.round(Number(form.value.unit_cost||0)*100),supplier:form.value.supplier,note:form.value.note});ElMessage.success('采购入库已登记，库存已更新');dialog.value=false;await load()}catch(e){onError(e)}finally{saving.value=false}}
onMounted(load)
</script>
<template><div><PageHeading title="采购管理" subtitle="登记到货并同步更新商品库存"><template #default><el-button type="primary" @click="open"><el-icon><CirclePlus/></el-icon>登记入库</el-button></template></PageHeading><section class="surface module-surface"><div class="surface-heading purchase-heading"><h2>最近入库记录</h2><span>{{ rows.length }} 条记录</span></div><div class="table-scroll"><el-table :data="rows" v-loading="loading" stripe style="width:100%" empty-text="暂无采购入库记录"><el-table-column prop="number" label="入库单号" min-width="190"/><el-table-column label="商品" min-width="220"><template #default="s">{{ s.row.product?.name }}</template></el-table-column><el-table-column label="数量" width="100"><template #default="s">{{ s.row.quantity }} {{ s.row.product?.unit }}</template></el-table-column><el-table-column label="采购成本" width="140"><template #default="s">{{ money(s.row.unit_cost_cents) }}</template></el-table-column><el-table-column prop="supplier" label="供应商" min-width="170"/><el-table-column label="入库时间" min-width="165"><template #default="s">{{ dateTime(s.row.created_at) }}</template></el-table-column></el-table></div></section><el-dialog v-model="dialog" title="登记采购入库" width="520px"><el-form label-position="top"><el-form-item label="商品" required><el-select v-model="form.product_id" filterable placeholder="选择商品"><el-option v-for="p in products" :key="p.id" :label="`${p.name}（${p.sku}）`" :value="p.id"/></el-select></el-form-item><el-form-item label="入库数量" required><el-input-number v-model="form.quantity" :min="1" :precision="0"/></el-form-item><el-form-item label="单位成本（元）"><el-input-number v-model="form.unit_cost" :min="0" :precision="2" :step="1"/></el-form-item><el-form-item label="供应商"><el-input v-model="form.supplier"/></el-form-item><el-form-item label="备注"><el-input v-model="form.note"/></el-form-item></el-form><div class="dialog-total"><span>本次采购成本</span><strong>{{ money(amount) }}</strong></div><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">确认入库</el-button></template></el-dialog></div></template>
